-- CodeDetective Academy PostgreSQL schema for Supabase.
-- 1. Run this file in the Supabase SQL editor (safe to re-run).
-- 2. Load case content: `npm run seed` (from backend/) or paste supabase/seed.sql.
create extension if not exists pgcrypto;
create table if not exists users(id uuid primary key default gen_random_uuid(),name text not null,email text not null unique,password_hash text not null,created_at timestamptz not null default now());
create table if not exists seasons(id text primary key,number integer not null,title text not null,language text not null,unlocked boolean not null default false);
create table if not exists cases(id text primary key,season_id text not null references seasons(id) on delete cascade,number text not null,title text not null,description text not null,objective text not null,difficulty text not null,xp_reward integer not null default 0 check(xp_reward>=0),prerequisite_case_id text references cases(id) on delete set null,stages jsonb not null default '[]'::jsonb,concept text not null,lesson jsonb not null default '{}'::jsonb,resolution jsonb not null default '{}'::jsonb);
create table if not exists challenges(id text primary key,case_id text not null unique references cases(id) on delete cascade,language text not null,starter_code text not null,hint text not null);
create table if not exists challenge_tests(id text primary key,challenge_id text not null references challenges(id) on delete cascade,name text not null,stdin text not null default '',expected_output text not null,hidden boolean not null default false);
create table if not exists evidence(id text primary key,case_id text not null references cases(id) on delete cascade,code text not null,text text not null,condition text not null);
create table if not exists progress(user_id uuid primary key references users(id) on delete cascade,xp integer not null default 0,level integer not null default 1,rank text not null default 'ROOKIE',streak integer not null default 0,cases_solved integer not null default 0,mastery jsonb not null default '{}'::jsonb,completed_lessons jsonb not null default '[]'::jsonb,completed_stages jsonb not null default '{}'::jsonb,discovered_evidence jsonb not null default '[]'::jsonb,unlocked_case_ids jsonb not null default '[]'::jsonb);
create table if not exists submissions(id uuid primary key default gen_random_uuid(),user_id uuid not null references users(id) on delete cascade,challenge_id text not null references challenges(id) on delete cascade,case_id text not null references cases(id) on delete cascade,passed boolean not null default false,score numeric not null default 0,tests_passed integer not null default 0,tests_total integer not null default 0,created_at timestamptz not null default now());
create table if not exists xp_transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references users(id) on delete cascade,case_id text references cases(id) on delete set null,amount integer not null,reason text not null,created_at timestamptz not null default now());
create index if not exists idx_cases_season on cases(season_id);create index if not exists idx_tests_challenge on challenge_tests(challenge_id);create index if not exists idx_evidence_case on evidence(case_id);create index if not exists idx_submissions_user on submissions(user_id,created_at desc);create index if not exists idx_submissions_case on submissions(case_id,created_at desc);create index if not exists idx_xp_user on xp_transactions(user_id,created_at desc);
alter table public.users enable row level security;alter table public.seasons enable row level security;alter table public.cases enable row level security;alter table public.challenges enable row level security;alter table public.challenge_tests enable row level security;alter table public.evidence enable row level security;alter table public.progress enable row level security;alter table public.submissions enable row level security;alter table public.xp_transactions enable row level security;

-- Progressive hints for the Detective Assistant (added after the first release; safe to re-run).
alter table public.challenges add column if not exists hints jsonb not null default '[]'::jsonb;
